// `import m` records the module object the program bound to `m`, so `sys.modules['m'] is m`.
pub fn sys_modules_set(name: &str, v: &V) -> R {
    if let V::Dict(d) = sys_modules() {
        d.borrow_mut().set(s(name), v.clone())?;
    }
    Ok(V::None)
}

